-- ============================================================
-- 京焼・清水焼（テーマID: 16, category_id: 6）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(6, 16, '京焼・清水焼の主要な産地として有名な道はどれか。', '嵐山渡月橋沿い', '清水坂・五条坂', '西陣堀川通', '金閣寺参道', 1, '京焼・清水焼は東山区の清水坂・五条坂（陶器坂）周辺が主な産地です。清水寺参道にも多くの陶器店が並んでおり、観光客も京焼・清水焼を買い求めに訪れます。', 1, false),
(6, 16, '江戸時代前期に茶陶を大成し「京焼中興の祖」とも呼ばれる陶芸家はだれか。', '奥田頴川', '尾形乾山', '野々村仁清', '仁阿弥道八', 2, '野々村仁清（ののむらにんせい、生没年不詳・17世紀活動）は京都・仁和寺門前で窯を開き、金彩・銀彩・多彩な上絵付けを駆使した優美な茶陶を制作し、「京焼中興の祖」とも称されます。', 1, false),
(6, 16, '野々村仁清の弟子で、琳派の美意識を陶芸に持ち込んだ陶芸家はだれか。', '奥田頴川', '青木木米', '尾形乾山', '仁阿弥道八', 2, '尾形乾山（おがたけんざん、1663〜1743年）は野々村仁清に陶技を学び、兄・尾形光琳と協力して琳派の絵付けを陶芸に持ち込みました。詩文・書・絵を組み合わせた独自の文人的な作風が特徴です。', 1, false),
(6, 16, '京焼に磁器の技術を導入した幕末の陶芸家はだれか。', '野々村仁清', '奥田頴川', '青木木米', '仁阿弥道八', 1, '奥田頴川（おくだえいせん、1753〜1811年）は清国（中国）の磁器技術を研究・独習し、京都で初めて磁器の焼成に成功した先駆者です。これにより京焼に磁器という新しいジャンルが加わりました。', 2, false),
(6, 16, '京焼・清水焼の特徴として最もあてはまるのはどれか。', '単色（一色）の焼き締め陶が主流', '絵付けが豊かで多彩な色使いの陶磁器', '鉄釉のみを使った素朴な焼き物', '薪窯のみで焼成する伝統的な焼き物', 1, '京焼・清水焼は絵付けの豊かさと多彩な色使いが最大の特徴です。上絵付け・金彩・銀彩など多様な技法を駆使し、雅やかな文様が描かれています。特定の様式に縛られない自由な発想も特徴のひとつです。', 1, false),
(6, 16, '京都の陶磁器産地「粟田口（あわたぐち）」で作られた焼き物の名称はどれか。', '仁和寺焼', '粟田焼', '御室焼', '清水焼', 1, '粟田焼（あわたやき）は京都市東山区粟田口周辺で作られた陶器で、江戸時代に茶陶・日用品として広く普及しました。粟田口焼とも呼ばれ、峻刻な表面と青みがかった釉薬が特徴です。', 2, false),
(6, 16, '野々村仁清が開いた窯の場所はどこか。', '東山五条付近', '仁和寺門前（御室）', '高台寺付近', '伏見区', 1, '野々村仁清は仁和寺（にんなじ）の門前、御室（おむろ）に窯を設けたことから「御室焼（おむろやき）」とも呼ばれます。仁和寺と深い関わりを持ちながら茶陶を制作しました。', 2, false),
(6, 16, '現代の京焼・清水焼作家が集積する産地として有名な工業団地はどれか。', '京陶団地（伏見区）', '山科工芸団地', '清水陶芸センター', '東山工芸団地', 0, '現在の京焼・清水焼の制作拠点としては、伏見区の「清水焼の郷（京陶団地）」が有名です。多くの窯元・作家が集まり、見学や購入も可能な施設が整っています。', 2, false),
(6, 16, '京都・仁和寺門前（御室）で作られた焼き物を何と呼ぶか。', '粟田焼', '御室焼', '高台寺焼', '嵯峨焼', 1, '御室焼（おむろやき）は野々村仁清が仁和寺門前に窯を開いたことから生まれた呼び名です。仁清の上絵付けの名品はほとんどがここで焼かれ、京焼の最高峰のひとつとして評価されています。', 2, false),
(6, 16, '江戸時代後期に活躍した「仁阿弥道八（にんなみどうはち）」の二代の窯として知られるのはどこか。', '高台寺焼の窯', '粟田口の窯', '御室焼の窯', '音羽焼の窯', 1, '高橋道八（高橋仁阿弥道八）は粟田口に窯を持ち、仁清・乾山の様式を踏まえつつ独自の作風を展開しました。その子孫は「道八」の名を代々継ぎ、現在も活躍する陶芸家系として知られています。', 3, false),
(6, 16, '京焼・清水焼の「上絵付け（うわえつけ）」の工程について正しいのはどれか。', '素焼きの段階で下絵を描く', '本焼きの後に絵の具を施し低温で焼く', '釉薬の下に絵を描く', '成形と同時に模様を刻み込む', 1, '上絵付けは本焼き後の器に上絵の具（ガラス質の顔料）で絵付けし、700〜800℃程度の低温で焼き付ける工程です。鮮やかな色彩が出せる一方で、絵の具が釉薬の上に乗るためデリケートな扱いが必要です。', 3, false),
(6, 16, '幕末から明治にかけて宮廷への献上品として作られた京焼の代名詞はどれか。', '京薩摩（きょうさつま）', '仁清写し', '乾山写し', '御本手（ごほんて）', 0, '「京薩摩（きょうさつま）」は幕末〜明治期に金彩・色絵を豪華に施した輸出・献上用の豪奢な陶磁器です。薩摩焼（鹿児島）の技法に京の絵付けを組み合わせたもので、欧米でも高く評価されました。', 3, false),
(6, 16, '清水焼の「窯元（かまもと）」が多く集まる「陶器まつり」が毎年行われる時期はどれか。', '3月', '5月', '8月（五条陶器まつり）', '12月', 2, '五条陶器まつりは毎年8月7〜10日に五条坂・茶わん坂周辺で開催される伝統の陶器市です。全国から陶芸家・窯元が出展し、安価に陶器が購入できる庶民的なイベントとして定着しています。', 2, false),
(6, 16, '尾形乾山と協力して有名な作品を制作した、乾山の兄で琳派の巨匠はだれか。', '俵屋宗達', '本阿弥光悦', '尾形光琳', '酒井抱一', 2, '尾形乾山の兄・尾形光琳（おがたこうりん、1658〜1716年）は琳派の代表的な画家です。乾山が作陶し光琳が絵付けをした「乾山作・光琳絵」の作品は現在でも最高峰の工芸品として珍重されています。', 1, false),
(6, 16, '「青木木米（あおきもくべい）」が京都で初めて磁器焼成に成功した師匠はだれか。', '野々村仁清', '奥田頴川', '仁阿弥道八', '楠部彌弌', 1, '青木木米（1767〜1833年）は奥田頴川に師事して磁器技法を習得し、後に中国の明・清代の磁器を研究して独自の文人的な作風を確立しました。煎茶道具の制作でも知られています。', 3, false),
(6, 16, '国の重要無形文化財「京焼・清水焼」の指定工芸技術として正しいのはどれか。', '染付・上絵付け・色絵など多様な技法が総合的に指定', '轆轤（ろくろ）による成形技術のみ', '登り窯による焼成技術のみ', '釉薬の調合技術のみ', 0, '国の重要無形文化財「京焼・清水焼」の指定は、染付・上絵付け・色絵・金彩など多様な技法を含む総合的な工芸技術として指定されています。特定技法だけでなく京焼の総体的な技術文化として評価されています。', 3, false),
(6, 16, '「御本手（ごほんて）」とはどのような陶器か。', '仁清が御所に献上した茶碗', '朝鮮の御本焼（こほんやき）を模倣した日本の陶器', '御室焼の代表的な技法', '皇室専用に作られた献上品', 1, '御本手（ごほんて）は朝鮮半島の「御本焼（こほんやき）」と呼ばれる陶磁器を模倣して日本で作られた茶碗の一種です。赤みがかった斑紋と柔らかい風合いが特徴で、茶人に珍重されました。', 3, false),
(6, 16, '京焼の産地として「粟田口」と「御室」のほかに知られる産地はどれか。', '嵯峨', '清水（音羽山付近）', '三条', '堀川', 1, '清水寺の音羽山付近（東山区清水）は「清水焼」の産地として古くから知られ、参道には多くの陶器店が並びます。「五条坂」「清水坂（茶わん坂）」一帯が今日でも京焼・清水焼の中心的な販売エリアです。', 1, false),
(6, 16, '京焼の文脈で「交趾（こうち）焼き」とはどのような焼き物か。', '中国・交趾地方（ベトナム）から伝来した焼き物の技法', '金属類を象嵌（ぞうがん）した高級焼き物', '土を多用した素朴な焼き物', '窯業が禁じられた時期に密造された焼き物', 0, '交趾焼（こうちやき）は中国や東南アジアから伝来した技法を基に、鮮やかな緑・黄・紫などの色釉を使った浮き彫り装飾が特徴の陶器です。京焼でも茶道具・香合などに盛んに作られています。', 3, false),
(6, 16, '毎年夏に五条坂周辺で開催される陶器市「五条陶器まつり」の起源はどれか。', '明治時代に窯元が自主的に始めたもの', '江戸時代から続く「土器市（かわらけいち）」に由来', '昭和初期に観光振興として始まった', '戦後の陶芸振興政策として始まった', 1, '五条陶器まつりは「土器市（かわらけいち）」とも呼ばれ、江戸時代に盂蘭盆会（お盆）の供物入れとして土器・陶器を売る市が立ったのが起源とされています。現在は全国規模の陶器市として発展しています。', 3, false);

